import { defineStore } from "pinia";
import { login as loginApi } from "@/api/auth";
import { StorageSerializers, useStorage } from "@vueuse/core";
import { useRouter } from "@/router";
/**
 * 用户认证Store
 */
export const useAuthStore = defineStore("auth", () => {
  const router = useRouter();
  // 用户信息对象
  const userInfo = useStorage("userInfo", null, localStorage, {
    serializer: StorageSerializers.object
  });
  // 访问令牌
  const accessToken = useStorage("accessToken", undefined);
  // 登录状态标识
  const isLoggedIn = computed(() => !!accessToken.value);
  // sts信息
  const stsInfo = useStorage("stsInfo", null, localStorage, {
    serializer: StorageSerializers.object
  });
  /**
   * 用户登录
   * @description 用户登录功能，获取并保存用户信息和访问令牌
   * @param {LoginParams} params - 登录参数
   * @returns {Promise<LoginResponse>} 登录结果
   * @throws {Error} 登录失败时抛出错误
   */
  const login = async params => {
    const response = await loginApi(params);
    userInfo.value = response.data.data.user;
    accessToken.value = response.data.data.accessToken;
    stsInfo.value = response.data.data.stsInfo;
    return response.data.data;
  };
  /**
   * 用户退出登录
   * @description 清除用户认证状态并从本地存储中移除认证数据
   */
  const logout = () => {
    clearAuthData();
    router.replace({
      name: "login"
    });
  };
  /**
   * 清除认证状态
   * @description 重置所有认证相关的响应式状态
   */
  const clearAuthData = () => {
    userInfo.value = null;
    accessToken.value = undefined;
    stsInfo.value = null;
  };
  return {
    isLoggedIn,
    userInfo,
    accessToken,
    stsInfo,
    login,
    logout,
    clearAuthData
  };
});